   155→        }
   156→        
   157→        .outcome.mfh-enquiries {
   158→            background-color: #fff8e1;
   159→            border-color: #ff8f00;
   160→        }
   161→        
   162→        .outcome.caller-enquiries {
   163→            background-color: #f3e5f5;
   164→            border-color: #7b1fa2;
   165→        }
   166→        
   167→        .outcome.caller-enquiries-recall {
