   200→        
   201→        .age-input input[type="number"] {
   202→            padding: 15px 25px;
   203→            border: 2px solid #1f4788;
   204→            border-radius: 8px;
   205→            font-size: 18px;
   206→            text-align: center;
   207→            width: 120px;
   208→            font-weight: bold;
