   217→</head>
   218→<body>
   219→    <div class="container">
   220→        <div class="header">
   221→            <h1>RCRP Decision Tree</h1>
   222→            <p>Main flow chart for police action assessment</p>
   223→        </div>
   224→        
   225→        <div id="question1" class="question-section active">
   226→            <div class="question">
   227→                Is police action required NOW?<br>
   228→                <small>To address a real, immediate risk to life or of serious harm to any person or group, identified or otherwise<br>
   229→                OR<br>
   230→                To prevent a child from suffering or being likely to suffer significant harm</small>
   231→            </div>
   232→            <div class="options">
   233→                <div class="option">
   234→                    <input type="radio" id="q1_yes" name="q1" value="yes">
   235→                    <label for="q1_yes">YES</label>
   236→                </div>
   237→                <div class="option">
   238→                    <input type="radio" id="q1_no" name="q1" value="no">
   239→                    <label for="q1_no">NO</label>
   240→                </div>
   241→            </div>
   242→        </div>
   243→        
   244→        <div id="question2" class="question-section">
   245→            <div class="question">Is the location of the individual who they have concerns for unknown?</div>
   246→            <div class="options">
   247→                <div class="option">
   248→                    <input type="radio" id="q2_yes" name="q2" value="yes">
   249→                    <label for="q2_yes">YES</label>
   250→                </div>
   251→                <div class="option">
   252→                    <input type="radio" id="q2_no" name="q2" value="no">
   253→                    <label for="q2_no">NO</label>
   254→                </div>
   255→            </div>
   256→        </div>
   257→        
   258→        <div id="question2a" class="question-section">
   259→            <div class="question">How old is the person?</div>
   260→            <div class="age-input">
   261→                <input type="number" id="age_input" name="age" min="0" max="120" placeholder="Enter age">
   262→            </div>
   263→        </div>
   264→        
   265→        <div id="question2b" class="question-section">
   266→            <div class="question">Is the person at risk of CCE (County Lines) or CSE (Child Sexual Exploitation)?</div>
   267→            <div class="options">
   268→                <div class="option">
   269→                    <input type="radio" id="q2b_yes" name="q2b" value="yes">
   270→                    <label for="q2b_yes">YES</label>
   271→                </div>
   272→                <div class="option">
   273→                    <input type="radio" id="q2b_no" name="q2b" value="no">
   274→                    <label for="q2b_no">NO</label>
   275→                </div>
   276→            </div>
   277→        </div>
   278→        
   279→        <div id="question2c" class="question-section">
   280→            <div class="question">Have reasonable enquiries been carried out?</div>
   281→            <div class="options">
   282→                <div class="option">
   283→                    <input type="radio" id="q2c_yes" name="q2c" value="yes">
   284→                    <label for="q2c_yes">YES</label>
   285→                </div>
   286→                <div class="option">
   287→                    <input type="radio" id="q2c_no" name="q2c" value="no">
   288→                    <label for="q2c_no">NO</label>
   289→                </div>
   290→            </div>
   291→        </div>
   292→        
   293→        <div id="question2d" class="question-section">
   294→            <div class="question">Are they an absconded patient?</div>
   295→            <div class="options">
   296→                <div class="option">
   297→                    <input type="radio" id="q2d_yes" name="q2d" value="yes">
   298→                    <label for="q2d_yes">YES</label>
   299→                </div>
   300→                <div class="option">
   301→                    <input type="radio" id="q2d_no" name="q2d" value="no">
   302→                    <label for="q2d_no">NO</label>
   303→                </div>
   304→            </div>
   305→        </div>
   306→        
   307→        <div id="question2e" class="question-section">
   308→            <div class="question">Has the health care facility carried out the five agreed checks?<br>
   309→                <small>1. Check CCTV<br>2. Check NOK (Next of Kin)<br>3. Rang the patient<br>4. Visited the home address<br>5. Checked the grounds</small>
   310→            </div>
   311→            <div class="options">
   312→                <div class="option">
   313→                    <input type="radio" id="q2e_yes" name="q2e" value="yes">
   314→                    <label for="q2e_yes">YES</label>
   315→                </div>
   316→                <div class="option">
   317→                    <input type="radio" id="q2e_no" name="q2e" value="no">
   318→                    <label for="q2e_no">NO</label>
   319→                </div>
   320→            </div>
   321→        </div>
   322→        
   323→        <div id="question2f" class="question-section">
   324→            <div class="question">Have reasonable enquiries been carried out?</div>
   325→            <div class="options">
   326→                <div class="option">
   327→                    <input type="radio" id="q2f_yes" name="q2f" value="yes">
   328→                    <label for="q2f_yes">YES</label>
   329→                </div>
   330→                <div class="option">
   331→                    <input type="radio" id="q2f_no" name="q2f" value="no">
   332→                    <label for="q2f_no">NO</label>
   333→                </div>
   334→            </div>
   335→        </div>
   336→        
   337→        <div id="question3" class="question-section">
   338→            <div class="question">Are they suspected to be in an address?</div>
   339→            <div class="options">
   340→                <div class="option">
   341→                    <input type="radio" id="q3_yes" name="q3" value="yes">
   342→                    <label for="q3_yes">YES</label>
   343→                </div>
   344→                <div class="option">
   345→                    <input type="radio" id="q3_no" name="q3" value="no">
   346→                    <label for="q3_no">NO</label>
   347→                </div>
   348→            </div>
   349→        </div>
   350→        
   351→        <div id="question3a" class="question-section">
   352→            <div class="question">Is there clear evidence that the person is in the address?<br>
   353→                <small>Consider the following indicators:
   354→                    <ul style="text-align: left; margin: 10px 0; padding-left: 20px;">
   355→                        <li>Can the person be seen?</li>
   356→                        <li>Is there blood that would suggest someone is injured?</li>
   357→                        <li>Is the person bed bound or cannot leave for some reason?</li>
   358→                    </ul>
   359→                </small>
   360→            </div>
   361→            <div class="options">
   362→                <div class="option">
   363→                    <input type="radio" id="q3a_yes" name="q3a" value="yes">
   364→                    <label for="q3a_yes">YES</label>
   365→                </div>
   366→                <div class="option">
   367→                    <input type="radio" id="q3a_no" name="q3a" value="no">
   368→                    <label for="q3a_no">NO</label>
   369→                </div>
   370→            </div>
   371→        </div>
   372→        
   373→        <div id="question4" class="question-section">
   374→            <div class="question">Does the concern relate to a mental health issue?</div>
   375→            <div class="options">
   376→                <div class="option">
   377→                    <input type="radio" id="q4_yes" name="q4" value="yes">
   378→                    <label for="q4_yes">YES</label>
   379→                </div>
   380→                <div class="option">
   381→                    <input type="radio" id="q4_no" name="q4" value="no">
   382→                    <label for="q4_no">NO</label>
   383→                </div>
   384→            </div>
   385→        </div>
   386→        
   387→        <div id="question5" class="question-section">
   388→            <div class="question">Does the concern relate to a physical health issue?</div>
   389→            <div class="options">
   390→                <div class="option">
   391→                    <input type="radio" id="q5_yes" name="q5" value="yes">
   392→                    <label for="q5_yes">YES</label>
   393→                </div>
   394→                <div class="option">
   395→                    <input type="radio" id="q5_no" name="q5" value="no">
   396→                    <label for="q5_no">NO</label>
   397→                </div>
   398→            </div>
   399→        </div>
   400→        
   401→        <div id="question6" class="question-section">
   402→            <div class="question">Does the risk relate to a physical health concern only?</div>
   403→            <div class="options">
   404→                <div class="option">
   405→                    <input type="radio" id="q6_yes" name="q6" value="yes">
   406→                    <label for="q6_yes">YES</label>
   407→                </div>
   408→                <div class="option">
   409→                    <input type="radio" id="q6_no" name="q6" value="no">
   410→                    <label for="q6_no">NO</label>
   411→                </div>
   412→            </div>
   413→        </div>
   414→        
   415→        <div id="question7" class="question-section">
   416→            <div class="question">Is the location of the individual who they have concerns for unknown?</div>
   417→            <div class="options">
   418→                <div class="option">
   419→                    <input type="radio" id="q7_yes" name="q7" value="yes">
   420→                    <label for="q7_yes">YES</label>
   421→                </div>
   422→                <div class="option">
   423→                    <input type="radio" id="q7_no" name="q7" value="no">
   424→                    <label for="q7_no">NO</label>
   425→                </div>
   426→            </div>
   427→        </div>
   428→        
   429→        <div id="question8" class="question-section">
   430→            <div class="question">Have reasonable enquiries been conducted to establish the persons whereabouts?</div>
   431→            <div class="options">
   432→                <div class="option">
   433→                    <input type="radio" id="q8_yes" name="q8" value="yes">
   434→                    <label for="q8_yes">YES</label>
   435→                </div>
   436→                <div class="option">
   437→                    <input type="radio" id="q8_no" name="q8" value="no">
   438→                    <label for="q8_no">NO</label>
   439→                </div>
   440→            </div>
   441→        </div>
   442→        
   443→        <div id="question9" class="question-section">
   444→            <div class="question">Is crime being reported?</div>
   445→            <div class="options">
   446→                <div class="option">
   447→                    <input type="radio" id="q9_yes" name="q9" value="yes">
   448→                    <label for="q9_yes">YES</label>
   449→                </div>
   450→                <div class="option">
   451→                    <input type="radio" id="q9_no" name="q9" value="no">
   452→                    <label for="q9_no">NO</label>
   453→                </div>
   454→            </div>
   455→        </div>
   456→        
   457→        <div id="question10" class="question-section">
   458→            <div class="question">Have other partner agencies been informed?</div>
   459→            <div class="options">
   460→                <div class="option">
   461→                    <input type="radio" id="q10_yes" name="q10" value="yes">
   462→                    <label for="q10_yes">YES</label>
   463→                </div>
   464→                <div class="option">
   465→                    <input type="radio" id="q10_no" name="q10" value="no">
   466→                    <label for="q10_no">NO</label>
   467→                </div>
   468→            </div>
   469→        </div>
   470→        
   471→        <div id="outcomes" class="question-section">
   472→            <h2>Outcome:</h2>
   473→            <div id="outcome-display"></div>
   474→        </div>
   475→        
   476→        <div class="navigation">
   477→            <button class="btn" id="nextBtn" onclick="nextQuestion()" disabled>Next</button>
   478→            <button class="btn reset-btn" onclick="resetForm()">Start Over</button>
   479→            <button class="btn copy-btn" id="copyBtn" onclick="copyResults()" style="display: none;">Copy Results</button>
   480→            <div id="copySuccess" class="copy-success" style="display: none;">Results copied to clipboard!</div>
   481→        </div>
   482→    </div>
   483→
   484→    <script>
   485→        let currentQuestion = 1;
   486→        const answers = {};
   487→        const questionTexts = {
   488→            1: "Is police action required NOW? To address a real, immediate risk to life or of serious harm to any person or group, identified or otherwise OR To prevent a child from suffering or being likely to suffer significant harm",
   489→            2: "Is the location of the individual who they have concerns for unknown?",
   490→            '2a': "How old is the person?",
   491→            '2b': "Is the person at risk of CCE (County Lines) or CSE (Child Sexual Exploitation)?",
   492→            '2c': "Have reasonable enquiries been carried out?",
   493→            '2d': "Are they an absconded patient?",
   494→            '2e': "Has the health care facility carried out the five agreed checks? (1. Check CCTV, 2. Check NOK, 3. Rang the patient, 4. Visited the home address, 5. Checked the grounds)",
   495→            '2f': "Have reasonable enquiries been carried out?",
   496→            3: "Are they suspected to be in an address?",
   497→            '3a': "Is there clear evidence that the person is in the address? (Consider: Can the person be seen? Is there blood suggesting injury? Is the person bed bound or cannot leave?)",
   498→            4: "Does the concern relate to a mental health issue?",
   499→            5: "Does the concern relate to a physical health issue?",
   500→            6: "Does the risk relate to a physical health concern only?",
   501→            7: "Is the location of the individual who they have concerns for unknown?",
   502→            8: "Have reasonable enquiries been conducted to establish the persons whereabouts?",
   503→            9: "Is crime being reported?",
   504→            10: "Have other partner agencies been informed?"
   505→        };
   506→        
   507→        function updateNextButton() {
   508→            const currentQuestionEl = document.getElementById(`question${currentQuestion}`);
   509→            const nextBtn = document.getElementById('nextBtn');
   510→            
   511→            let answered = false;
   512→            
   513→            // Check for age input
   514→            if (currentQuestion === '2a') {
   515→                const ageInput = document.getElementById('age_input');
   516→                answered = ageInput.value.trim() !== '' && parseInt(ageInput.value) >= 0;
   517→            } else {
   518→                // Check radio buttons
   519→                const radios = currentQuestionEl.querySelectorAll('input[type="radio"]');
   520→                for (let radio of radios) {
   521→                    if (radio.checked) {
   522→                        answered = true;
   523→                        break;
   524→                    }
   525→                }
   526→            }
   527→            
   528→            nextBtn.disabled = !answered;
   529→        }
   530→        
   531→        function nextQuestion() {
   532→            const currentQuestionEl = document.getElementById(`question${currentQuestion}`);
   533→            
   534→            let selectedValue = '';
   535→            
   536→            // Handle age input
   537→            if (currentQuestion === '2a') {
   538→                const ageInput = document.getElementById('age_input');
   539→                selectedValue = ageInput.value;
   540→                answers[`q${currentQuestion}`] = selectedValue;
   541→            } else {
   542→                // Handle radio buttons
   543→                const radios = currentQuestionEl.querySelectorAll('input[type="radio"]');
   544→                for (let radio of radios) {
   545→                    if (radio.checked) {
   546→                        selectedValue = radio.value;
   547→                        break;
   548→                    }
   549→                }
   550→                answers[`q${currentQuestion}`] = selectedValue;
   551→            }
   552→            
   553→            // Hide current question
   554→            currentQuestionEl.classList.remove('active');
   555→            
   556→            // Decision logic
   557→            if (currentQuestion === 1) {
   558→                if (selectedValue === 'yes') {
   559→                    showOutcome('police-attendance', 'Police Attendance Required');
   560→                    return;
   561→                } else {
   562→                    currentQuestion = 2;
   563→                }
   564→            } else if (currentQuestion === 2) {
   565→                if (selectedValue === 'yes') {
   566→                    currentQuestion = '2a';
   567→                } else {
   568→                    currentQuestion = 3;
   569→                }
   570→            } else if (currentQuestion === '2a') {
   571→                const age = parseInt(selectedValue);
   572→                if (age <= 13) {
   573→                    showOutcome('mfh-policy', 'Follow MFH policy');
   574→                    return;
   575→                } else if (age >= 14 && age <= 17) {
   576→                    currentQuestion = '2b';
   577→                } else if (age >= 18) {
   578→                    currentQuestion = '2d';
   579→                } else {
   580→                    showOutcome('police-attendance', 'Missing Persons Pathways - Grade and consider police deployment');
   581→                    return;
   582→                }
   583→            } else if (currentQuestion === '2b') {
