function previousQuestion() {
    if (questionHistory.length > 1) {
        // Remove current question from history
        questionHistory.pop();

        // Hide current question
        const currentQuestionEl = document.getElementById(`question${currentQuestion}`);
        currentQuestionEl.classList.remove('active');

        // Go back to previous question
        currentQuestion = questionHistory[questionHistory.length - 1];

        // Show previous question
        const prevQuestionEl = document.getElementById(`question${currentQuestion}`);
        prevQuestionEl.classList.add('active');

        // Clear the answer for the question we went back from
        const nextQuestionKey = `q${questionHistory[questionHistory.length]}` || `q${Object.keys(answers).pop().replace('q', '')}`;
        if (answers[nextQuestionKey]) {
            delete answers[nextQuestionKey];
        }

        updatePreviousButton();

        // Hide outcomes if we're going back from an outcome
        const outcomeEl = document.getElementById('outcomes');
        if (outcomeEl.classList.contains('active')) {
            outcomeEl.classList.remove('active');
            document.getElementById('outcome-display').innerHTML = '';
            document.getElementById('copyBtn').style.display = 'none';
        }
    }
}

// Add event listeners to all radio buttons and age input
document.addEventListener('DOMContentLoaded', function() {
    const radios = document.querySelectorAll('input[type="radio"]');
    radios.forEach(radio => {
        radio.addEventListener('change', autoAdvance);
    });

    // Add event listener for age input with debouncing
    const ageInput = document.getElementById('age_input');
    if (ageInput) {
        let ageTimeout;
        ageInput.addEventListener('input', function() {
            clearTimeout(ageTimeout);
            const value = this.value.trim();
            if (value !== '' && parseInt(value) >= 0) {
                ageTimeout = setTimeout(() => {
                    autoAdvance();
                }, 1000); // Wait 1 second after user stops typing
            }
        });

        // Also advance on Enter key
        ageInput.addEventListener('keypress', function(e) {
            if (e.key === 'Enter') {
                clearTimeout(ageTimeout);
                const value = this.value.trim();
                if (value !== '' && parseInt(value) >= 0) {
                    autoAdvance();
                }
            }
        });
    }

    // Initialize previous button state
    updatePreviousButton();
});

