    border-color: #153a70;
    box-shadow: 0 0 10px rgba(31, 71, 136, 0.3);
}

.multi-select-options {
    margin: 20px 0;
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 10px;
}

.checkbox-option {
    display: flex;
    align-items: center;
    padding: 10px;
    background-color: white;
    border: 2px solid #1f4788;
    border-radius: 8px;
    cursor: pointer;
    transition: all 0.3s ease;
}

.checkbox-option:hover {
    background-color: #f0f4ff;
    transform: translateY(-1px);
    box-shadow: 0 2px 6px rgba(31, 71, 136, 0.2);
}

.checkbox-option input[type="checkbox"] {
    margin-right: 10px;
    width: 18px;
    height: 18px;
    accent-color: #1f4788;
}

.checkbox-option label {
    flex: 1;
    font-weight: bold;
    color: #1f4788;
    cursor: pointer;
    margin: 0;
    padding: 0;
}

.checkbox-option input[type="checkbox"]:checked + label {
    color: #153a70;
}

.free-text-input {
    margin: 20px 0;
}

.free-text-input label {
    display: block;
    font-weight: bold;
    color: #1f4788;
    margin-bottom: 10px;
}

.free-text-input textarea {
    width: 100%;
    min-height: 100px;
    padding: 15px;
    border: 2px solid #1f4788;
    border-radius: 8px;
    font-size: 14px;
    font-family: Arial, sans-serif;
    resize: vertical;
    box-sizing: border-box;
}

.free-text-input textarea:focus {
    outline: none;
    border-color: #153a70;
    box-shadow: 0 0 10px rgba(31, 71, 136, 0.3);
}

.multi-select-navigation {
    text-align: center;
    margin: 20px 0;
}

.multi-select-navigation button {
    background-color: #1f4788;
    color: white;
    border: none;
    padding: 10px 20px;
    border-radius: 5px;
    cursor: pointer;
    font-size: 16px;
}

.multi-select-navigation button:hover:not(:disabled) {
    background-color: #153a70;
}

.multi-select-navigation button:disabled {
    background-color: #ccc;
    cursor: not-allowed;
}

