    } else if (type === 'caller-enquiries') {
        outcomeClass += ' caller-enquiries';
    } else if (type === 'caller-enquiries-recall') {
        outcomeClass += ' caller-enquiries-recall';
    }

    outcomeDisplay.innerHTML = `<div class="${outcomeClass}">${message}</div>`;
    outcomeEl.classList.add('active');

    document.getElementById('prevBtn').style.display = 'none';
    document.getElementById('copyBtn').style.display = 'inline-block';
}

