function copyResults() {
    let resultText = "RCRP Decision Toolkit\n";
    resultText += "=" + "=".repeat(21) + "\n\n";

    // Add all answered questions
    const answeredQuestions = Object.keys(answers).sort();
    answeredQuestions.forEach(questionKey => {
        const questionNum = questionKey.replace('q', '');
        const questionText = questionTexts[questionNum];
        const answer = answers[questionKey].toUpperCase();
        resultText += `Q: ${questionText}\n`;
        resultText += `A: ${answer}\n\n`;
    });

    // Add outcome
    const outcomeText = document.getElementById('outcome-display').textContent;
    resultText += `OUTCOME: ${outcomeText}\n\n`;

    // Add timestamp
    const now = new Date();
    resultText += `Generated: ${now.toLocaleString()}\n`;

    // Copy to clipboard
    navigator.clipboard.writeText(resultText).then(() => {
        document.getElementById('copySuccess').style.display = 'block';
        setTimeout(() => {
            document.getElementById('copySuccess').style.display = 'none';
        }, 3000);
    }).catch(err => {
        // Fallback for older browsers
        const textArea = document.createElement('textarea');
        textArea.value = resultText;
        document.body.appendChild(textArea);
        textArea.select();
        document.execCommand('copy');
        document.body.removeChild(textArea);

        document.getElementById('copySuccess').style.display = 'block';
        setTimeout(() => {
            document.getElementById('copySuccess').style.display = 'none';
        }, 3000);
    });
}

